SELECT SUM(cot) FROM (
	SELECT 
		COUNT(1) cot
	FROM
		WFL_TRD_FIN_PRODUCT_DEAL_TOTAL
	INNER JOIN WFL_PA_TRD_FIN_DEAL_TOTAL
		ON WFL_PA_TRD_FIN_DEAL_TOTAL.TOTLE_TRADE_ID = WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID
		AND WFL_PA_TRD_FIN_DEAL_TOTAL.PA_BUSS_TYPE = #{PA_BUSS_TYPE,jdbcType=VARCHAR}
	INNER JOIN FIN_PRODUCT_ADD
		ON FIN_PRODUCT_ADD.PORTFOLIO_ID  = WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.PORTFOLIO_ID
	INNER JOIN FIN_PRODUCT on FIN_PRODUCT.FINPROD_MARKET_ID = #{FINPROD_MARKET_ID,jdbcType=VARCHAR}
	WHERE
	    WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.WORKFLOW_STATUS = #{WORKFLOW_STATUS,jdbcType=VARCHAR}
		AND WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.PORTFOLIO_ID = #{FINPROD_MARKET_ID,jdbcType=VARCHAR}
	UNION ALL
	SELECT 
		COUNT(1) cot
	FROM
		PTL_CASH_POSITION_FLOW
	WHERE
	    PTL_CASH_POSITION_FLOW.SPLIT_TYPE = #{SPLIT_TYPE,jdbcType=VARCHAR}

			AND PTL_CASH_POSITION_FLOW.SEQNO IN(

		            #{item}

			)

)

